/* @lc app=leetcode id=2312 lang=kotlin */ class Solution { fun sellingWood(m: Int, n: Int, prices: Array<IntArray>): Long = Array(m + 1) { LongArray(n + 1) }.apply { prices.forEach { this[it[0]][it[1]] = Math.max(this[it[0]][it[1]], it[2].toLong()) }.run { (1..m).forEach { i -> (1..n).forEach { j -> (1 until i).forEach { k -> this@apply[i][j] = Math.max(this@apply[i][j], this@apply[k][j] + this@apply[i - k][j]) }.run { (1 until j).forEach { k -> this@apply[i][j] = Math.max(this@apply[i][j], this@apply[i][k] + this@apply[i][j - k]) } } } } } }[m][n] }